def find_smallest_number(lst):
    return min(lst)

def find_largest_number(lst):
    return max(lst)

def strange_sort_list(lst):
    sorted_list = []
    lst_copy = lst.copy()

    while lst_copy:
        smallest = find_smallest_number(lst_copy)
        sorted_list.append(smallest)
        lst_copy.remove(smallest)

        if lst_copy:
            largest = find_largest_number(lst_copy)
            sorted_list.append(largest)
            lst_copy.remove(largest)

    return sorted_list

# Test cases
print(strange_sort_list([1, 2, 3, 4]))  # Output: [1, 4, 2, 3]
print(strange_sort_list([5, 5, 5, 5]))  # Output: [5, 5, 5, 5]
print(strange_sort_list([]))  # Output: []

